module dna_program_comparator (input clk, input rst_n, input start, input [7:0] op_type, input [15:0] op_pos, input [7:0] op_char, input program_sel, output reg result, output reg done, output reg error); reg [2:0] state; reg [3:0] prog1_count, prog2_count; reg program1_end, program2_end; reg [7:0] raw_ops1_type[8], raw_ops1_pos[8], raw_ops1_char[8]; reg [7:0] raw_ops2_type[8], raw_ops2_pos[8], raw_ops2_char[8]; reg [2:0] sim1_type[8], sim1_pos[8], sim1_char[8]; reg [3:0] sim1_count; reg [2:0] sim2_type[8], sim2_pos[8], sim2_char[8]; reg [3:0] sim2_count; reg error_flag; reg result_reg, done_reg; reg [3:0] copy_counter1, copy_counter2; localparam IDLE = 3'd0, READ_OPS1 = 3'd1, SIMPLIFY1 = 3'd2, READ_OPS2 = 3'd3, SIMPLIFY2 = 3'd4, COMPARE = 3'd5, DONE = 3'd6; always_ff @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= IDLE; prog1_count <= 4'd0; prog2_count <= 4'd0; program1_end <= 1'b0; program2_end <= 1'b0; error_flag <= 1'b0; result_reg <= 1'b0; done_reg <= 1'b0; sim1_count <= 4'd0; sim2_count <= 4'd0; copy_counter1 <= 4'd0; copy_counter2 <= 4'd0; for (int i=0; i<8; i++) begin raw_ops1_type[i] <= 8'd0; raw_ops1_pos[i] <= 16'd0; raw_ops1_char[i] <= 8'd0; raw_ops2_type[i] <= 8'd0; raw_ops2_pos[i] <= 16'd0; raw_ops2_char[i] <= 8'd0; sim1_type[i] <= 8'd0; sim1_pos[i] <= 16'd0; sim1_char[i] <= 8'd0; sim2_type[i] <= 8'd0; sim2_pos[i] <= 16'd0; sim2_char[i] <= 8'd0; end end else begin case (state) IDLE: begin if (start) state <= READ_OPS1; end READ_OPS1: begin if (program_sel == 1) error_flag <= 1'b1; else begin if (op_type == 3) begin program1_end <= 1'b1; if (prog1_count > 8) error_flag <= 1'b1; state <= SIMPLIFY1; end else if (op_type != 0) begin if (prog1_count < 8) begin raw_ops1_type[prog1_count] <= op_type; raw_ops1_pos[prog1_count] <= op_pos; if (op_type == 1) raw_ops1_char[prog1_count] <= op_char; prog1_count <= prog1_count + 1; end else error_flag <= 1'b1; end end end end SIMPLIFY1: begin if (copy_counter1 < prog1_count) begin sim1_type[copy_counter1] <= raw_ops1_type[copy_counter1]; sim1_pos[copy_counter1] <= raw_ops1_pos[copy_counter1]; if (raw_ops1_type[copy_counter1] == 1) sim1_char[copy_counter1] <= raw_ops1_char[copy_counter1]; copy_counter1 <= copy_counter1 + 1; end else begin copy_counter1 <= 4'd0; state <= READ_OPS2; end end READ_OPS2: begin if (program_sel == 0) error_flag <= 1'b1; else begin if (op_type == 3) begin program2_end <= 1'b1; if (prog2_count > 8) error_flag <= 1'b1; state <= SIMPLIFY2; end else if (op_type != 0) begin if (prog2_count < 8) begin raw_ops2_type[prog2_count] <= op_type; raw_ops2_pos[prog2_count] <= op_pos; if (op_type == 1) raw_ops2_char[prog2_count] <= op_char; prog2_count <= prog2_count + 1; end else error_flag <= 1'b1; end end end end SIMPLIFY2: begin if (copy_counter2 < prog2_count) begin sim2_type[copy_counter2] <= raw_ops2_type[copy_counter2]; sim2_pos[copy_counter2] <= raw_ops2_pos[copy_counter2]; if (raw_ops2_type[copy_counter2] == 1) sim2_char[copy_counter2] <= raw_ops2_char[copy_counter2]; copy_counter2 <= copy_counter2 + 1; end else begin copy_counter2 <= 4'd0; state <= COMPARE; end end COMPARE: begin result_reg <= (sim1_count != sim2_count) ? 1'b1 : 1'b0; done_reg <= 1'b1; state <= DONE; end DONE: begin endcase end endmodule